Q: Custom Name for Formbuilder Reactive Form - Angular 7 A: <p>Well, all the answer don't take account: a FormGroup is some that belong to the .ts, have no relation with the .html. the only &quot;glue&quot; is the formControlName, so .ts have no idea about the label.</p>
<p>The solution is create a directive that have &quot;access&quot; to the .html</p>
<p>The rule is, e.g. if all our inputs are in the way</p>
<pre><code>      &lt;div class=&quot;form-group&quot;&gt;
        &lt;label for=&quot;email&quot;&gt;Email&lt;/label&gt;
        &lt;input type=&quot;email&quot; formControlName=&quot;email&quot;/&gt;
        &lt;div class=&quot;error&quot;&gt;&lt;/div&gt;
      &lt;/div&gt;
</code></pre>
<p>We can create a directive in the way</p>
<pre><code>@Directive({
  selector: '.error',
})
export class ErrorDirective implements AfterViewInit, OnDestroy {
  labelText: string = '';
  control?: FormControl&lt;any&gt; | null;
  sub?: Subscription;

  //in constructor inject the FormGroupDirective using &quot;@Host&quot;. This
  //give us access to the &quot;formGroup&quot;

  constructor(@Host() private form: FormGroupDirective,private el: ElementRef) {}
  ngAfterViewInit() {
    //we get the htmlElements &quot;label&quot; and &quot;input&quot;
    const label =
      this.el.nativeElement.parentElement.getElementsByTagName('label')[0];
    const input =
      this.el.nativeElement.parentElement.querySelector('[formControlName]');

    this.labelText = label.innerText;  //get the &quot;innerText&quot; of the label
    this.control = this.form.form.get(
      input.getAttribute('formControlName')  //get the &quot;formControl&quot;
    ) as FormControl;

    //we subscribe to the &quot;control&quot; statusChange
    this.sub = this.control.statusChanges
      .pipe(startWith(null))
      .subscribe((_) =&gt; {
        //we ask about errors
        if (!this.control?.errors) {
          this.el.nativeElement.innerText = '';
          return;
        }
        if (this.control?.errors['required']) {
          this.el.nativeElement.innerText = this.labelText + ' required';
          return;
        }
        this.el.nativeElement.innerText = this.labelText + ' not valid';
      });
  }
  ngOnDestroy() {
    this.sub &amp;&amp; this.sub.unsubscribe(); //unsubscribe
  }
}

</code></pre>
